/bin/bash -lc 'verify_tmp=$(find "$TMPDIR" -maxdepth 1 -type d -name '"'iiti-verify.*' | sort | tail -1)
python3 - \""'$verify_tmp/academic_program.html" <<'"'PY'
from bs4 import BeautifulSoup
import sys
s=BeautifulSoup(open(sys.argv[1],encoding='utf-8'),'html.parser')
for i,t in enumerate(s.find_all('table')):
    txt=t.get_text('\\n',strip=True)
    if 'Bachelor of Technology' in txt or 'Doctor of Philosophy' in txt:
      print('TABLE',i,'rows',len(t.find_all('tr')))
      for tr in t.find_all('tr'):
        cells=[c.get_text(' ',strip=True) for c in tr.find_all(['th','td'])]
        if cells: print(' | '.join(cells))
PY"

